{
    if (ctx == NULL || ctx->md_info == NULL) {
        return;
    }

    if (ctx->md_ctx != NULL) {

        switch (ctx->md_info->type) {

            case MBEDTLS_MD_SHA1:
                mbedtls_sha1_free(ctx->md_ctx);
                break;

            case MBEDTLS_MD_SHA256:
                mbedtls_sha256_free(ctx->md_ctx);
